#[test]fn system_attributes_all_records_and_order(){let actual=migration_catalog::system_attributes();let expected=reference::system_attributes();let rendered:Vec<String>=actual.iter().map(|r|format!("{{\"name\":{},\"uuid\":{},\"description\":{:?},\"multivalue\":{},\"unique\":{},\"phantom\":{},\"sync_allowed\":{},\"replicated\":{},\"indexed\":{},\"syntax\":{}}}",r.name,r.uuid,r.description,r.multivalue,r.unique,r.phantom,r.sync_allowed,r.replicated,r.indexed,r.syntax)).collect();assert_eq!(rendered,expected,"all selected fields and order: system_attributes");}
